mapper.select:
SELECT ur.user_id FROM sys_user_role ur
INNER JOIN sys_user u ON u.id = ur.user_id AND u.deleted = 0
WHERE ur.role_id = #{roleId}

SELECT EXISTS (
    SELECT 1 FROM sys_user_role ur
    INNER JOIN sys_role r ON r.id = ur.role_id AND r.role_code = 'superadmin' AND r.deleted = 0
    INNER JOIN sys_user u ON u.id = ur.user_id AND u.deleted = 0
    WHERE ur.user_id = #{userId}
)

SELECT r.* FROM sys_user_role ur
INNER JOIN sys_role r ON r.id = ur.role_id AND r.deleted = 0
WHERE ur.user_id = #{userId}
